#include "zp_c/fatal.h"

#include <stdarg.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// =========================================================================================================================================
// =========================================================================================================================================
// fatal_z: Abort the program with a fatal error message. Prints the message to stderr with red color formatting and then calls abort().
// Accepts a format string and variadic arguments (like printf).
// =========================================================================================================================================
// =========================================================================================================================================
void fatal_z(const char* format, ...)
{
    va_list args;
    va_start(args, format);
    fprintf(stderr, "\033[31mfatal: ");
    vfprintf(stderr, format, args);
    fprintf(stderr, "\033[0m\n");
    va_end(args);
    fflush(stderr);
    abort();
}

// =========================================================================================================================================
// =========================================================================================================================================
// fatal_check_z: Check if a pointer is null and abort with a fatal error if it is.
// =========================================================================================================================================
// =========================================================================================================================================
void fatal_check_z(const void* ptr, const char* message, ...)
{
    if (!ptr)
    {
        va_list args;
        va_start(args, message);
        fprintf(stderr, "\033[31mfatal: ");
        vfprintf(stderr, message, args);
        fprintf(stderr, "\033[0m\n");
        va_end(args);
        fflush(stderr);
        abort();
    }
}

// =========================================================================================================================================
// =========================================================================================================================================
// fatal_check_bool_z: Check if a boolean value is false and abort with a fatal error if it is.
// =========================================================================================================================================
// =========================================================================================================================================
void fatal_check_bool_z(bool value, const char* message)
{
    if (!value) fatal_z(message);
}

// =========================================================================================================================================
// =========================================================================================================================================
// fatal_alloc_z: Allocate memory using malloc and abort with a fatal error if allocation fails. The allocated memory is zero-initialized.
// =========================================================================================================================================
// =========================================================================================================================================
void* fatal_alloc_z(size_t size, const char* message)
{
    void* ptr = malloc(size);
    if (!ptr)
    {
        fatal_z(message);
    }
    memset(ptr, 0, size);
    return ptr;
}
